import json
import os
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RUN_CONFIG = json.loads((ROOT / "config" / "run.config.json").read_text())

def get_environment() -> str:
    environment = os.getenv("TEST_ENV", RUN_CONFIG["environment"])
    available = sorted(path.stem for path in (ROOT / "test-data").glob("*.json"))
    if environment not in available:
        raise ValueError(f'Unknown environment "{environment}". Available: {", ".join(available)}')
    return environment

def get_test_data() -> dict:
    return json.loads((ROOT / "test-data" / f"{get_environment()}.json").read_text())
